/**
 * Typed API client + TanStack Query hooks (task T0.1/T0.2; more hooks are added as routes land).
 *
 * Where this sits in the app
 * --------------------------
 * Components never call fetch() directly. They use these hooks, which:
 *   1. call the backend through `openapi-fetch`, typed by src/api/types.ts (generated by `make types`
 *      from the backend's models, so a renamed field is a compile error here, not a runtime bug);
 *   2. cache results with TanStack Query (keyed by dataset + time), so moving the time machine
 *      refetches only what changed.
 *
 * The frontend does no math on plans or costs: every number comes from the API (plan.md rule).
 */
import { useQuery } from "@tanstack/react-query";
import createClient from "openapi-fetch";

import type { components, paths } from "./types";

/** Shorthand for the generated schema types, e.g. `Schemas["Alert"]`. */
export type Schemas = components["schemas"];
export type Alert = Schemas["Alert"];
export type Event = Schemas["Event"];
export type StateResponse = Schemas["StateResponse"];
export type PlanResponse = Schemas["PlanResponse"];
export type ReplayResult = Schemas["ReplayResult"];
export type DatasetInfo = Schemas["DatasetInfo"];
export type NetworkResponse = Schemas["NetworkResponse"];

/**
 * The client. `baseUrl` is empty because the API is on the same origin:
 * in dev, Vite proxies /api to the backend (vite.config.ts); in production, set VITE_API_BASE.
 */
export const api = createClient<paths>({ baseUrl: import.meta.env.VITE_API_BASE ?? "" });

/**
 * Turn an openapi-fetch result into data or a thrown Error, so TanStack Query can show error states.
 * FastAPI errors carry a `detail` string (e.g. "Not implemented yet (task T2.5)"), which we surface.
 */
async function unwrap<T>(request: Promise<{ data?: T; error?: unknown; response: Response }>): Promise<T> {
  const { data, error, response } = await request;
  if (error !== undefined || data === undefined) {
    const detail = (error as { detail?: unknown } | undefined)?.detail;
    throw new Error(`${response.status}: ${typeof detail === "string" ? detail : response.statusText}`);
  }
  return data;
}

/** Backend liveness + mock flag. The header shows a MOCK DATA badge when `mock` is true. */
export function useHealth() {
  return useQuery({ queryKey: ["health"], queryFn: () => unwrap(api.GET("/api/health")) });
}

/** Every dataset folder the backend found (dataset switcher, T6.2). */
export function useDatasets() {
  return useQuery({ queryKey: ["datasets"], queryFn: () => unwrap(api.GET("/api/datasets")) });
}

/** Static network + ops + time range for one dataset (map, limits, time-machine range). */
export function useNetwork(ds: string | null) {
  return useQuery({
    queryKey: ["network", ds],
    enabled: ds !== null,
    queryFn: () => unwrap(api.GET("/api/{ds}/network", { params: { path: { ds: ds! } } })),
  });
}

/**
 * The network as of one moment: facilities, ordered alerts, events.
 * `at` = time-machine position in unix seconds, or null for the dataset's "now".
 * (Named useNetworkState so it doesn't clash with React's useState.)
 */
export function useNetworkState(ds: string | null, at: number | null) {
  return useQuery({
    queryKey: ["state", ds, at],
    enabled: ds !== null,
    queryFn: () => unwrap(api.GET("/api/{ds}/state", { params: { path: { ds: ds! }, query: { at } } })),
  });
}

/** Plan panel data for one pump failure (cheapest, long run, do nothing, alternatives, traces). */
export function usePlan(ds: string | null, eventId: string | null, at: number | null) {
  return useQuery({
    queryKey: ["plan", ds, eventId, at],
    enabled: ds !== null && eventId !== null,
    queryFn: () =>
      unwrap(api.GET("/api/{ds}/plan/{event_id}", { params: { path: { ds: ds!, event_id: eventId! }, query: { at } } })),
  });
}

/** One sensor's readings for the trend charts (T6.6). */
export function useSeries(ds: string | null, asset: string | null, metric: string) {
  return useQuery({
    queryKey: ["series", ds, asset, metric],
    enabled: ds !== null && asset !== null,
    queryFn: () =>
      unwrap(api.GET("/api/{ds}/series", { params: { path: { ds: ds! }, query: { asset: asset!, metric } } })),
  });
}

/** Savings replay for the whole window (T6.10). */
export function useReplay(ds: string | null, mode: "cheapest" | "long_run" = "long_run") {
  return useQuery({
    queryKey: ["replay", ds, mode],
    enabled: ds !== null,
    queryFn: () => unwrap(api.GET("/api/{ds}/replay", { params: { path: { ds: ds! }, query: { mode } } })),
  });
}
